cat > "app/blog/[slug]/page.tsx" << 'EOF'
import { getAllPosts, getPostBySlug } from "@/lib/blog/get-posts";
import { marked } from "marked";
import Link from "next/link";

interface Params {
  slug: string;
}

export async function generateStaticParams() {
  const posts = getAllPosts();
  return posts.map((post) => ({
    slug: post.slug,
  }));
}

export default async function BlogPost({
  params,
}: {
  params: Promise<Params>;
}) {
  const { slug } = await params;
  const post = getPostBySlug(slug);
  const htmlContent = await marked(post.content);

  return (
    <article className="max-w-2xl mx-auto">
      <Link
        href="/"
        className="text-blue-600 hover:text-blue-800 mb-6 inline-block"
      >
        ← Back to all posts
      </Link>

      <header className="mb-8">
        <h1 className="text-4xl font-bold text-gray-900 mb-4">{post.title}</h1>
        <div className="flex items-center justify-between">
          <time className="text-gray-600">
            {new Date(post.date).toLocaleDateString("en-US", {
              year: "numeric",
              month: "long",
              day: "numeric",
            })}
          </time>
          {post.category && (
            <span className="text-xs bg-blue-100 text-blue-800 px-3 py-1 rounded-full">
              {post.category}
            </span>
          )}
        </div>
      </header>

      <div
        className="prose max-w-none text-gray-700 leading-relaxed"
        dangerouslySetInnerHTML={{ __html: htmlContent }}
      />
    </article>
  );
}
EOF

cat > memo.js << 'EOF'
#!/usr/bin/env node
// 메모 프로그램. JSON 파일에 메모를 저장한다.
import readline from 'node:readline';
import fs from 'node:fs';
import path from 'node:path';

const memoFile = path.join(process.env.HOME, '.memos.json');

const loadMemos = () => {
  try {
    if (fs.existsSync(memoFile)) {
      const data = fs.readFileSync(memoFile, 'utf-8');
      return JSON.parse(data);
    }
  } catch (e) {}
  return [];
};

const saveMemos = (memos) => {
  fs.writeFileSync(memoFile, JSON.stringify(memos, null, 2));
};

const memos = loadMemos();
const rl = readline.createInterface({ input: process.stdin, output: process.stdout });

console.log('메모를 입력하세요. "목록" 은 전체 보기, "끝" 은 종료.');
rl.on('line', (line) => {
  const text = line.trim();
  if (text === '끝') {
    saveMemos(memos);
    return rl.close();
  }
  if (text === '목록') {
    memos.forEach((memo, i) => console.log(`${i + 1}. ${memo}`));
    return;
  }
  if (text !== '') {
    memos.push(text);
    saveMemos(memos);
  }
});
EOF

