<!DOCTYPE html>
<html lang="ko">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>할 일 목록 앱</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen', sans-serif;
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            min-height: 100vh;
            display: flex;
            justify-content: center;
            align-items: center;
            padding: 20px;
        }

        .container {
            width: 100%;
            max-width: 500px;
            background: white;
            border-radius: 15px;
            box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
            overflow: hidden;
            display: flex;
            flex-direction: column;
            max-height: 90vh;
        }

        .header {
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            color: white;
            padding: 25px;
            text-align: center;
        }

        .header h1 {
            font-size: 28px;
            margin-bottom: 10px;
            font-weight: 700;
        }

        .stats {
            font-size: 14px;
            opacity: 0.9;
        }

        .stat-text {
            background: rgba(255, 255, 255, 0.2);
            padding: 4px 12px;
            border-radius: 20px;
            display: inline-block;
        }

        .input-group {
            display: flex;
            gap: 8px;
            padding: 20px;
            border-bottom: 1px solid #e0e0e0;
            background: #f9f9f9;
        }

        .input {
            flex: 1;
            padding: 12px 16px;
            border: 2px solid #e0e0e0;
            border-radius: 8px;
            font-size: 14px;
            font-family: inherit;
            transition: border-color 0.2s;
        }

        .input:focus {
            outline: none;
            border-color: #667eea;
        }

        .btn-add {
            padding: 12px 24px;
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            color: white;
            border: none;
            border-radius: 8px;
            font-weight: 600;
            cursor: pointer;
            font-size: 14px;
            transition: transform 0.2s, box-shadow 0.2s;
        }

        .btn-add:hover {
            transform: translateY(-2px);
            box-shadow: 0 8px 16px rgba(102, 126, 234, 0.4);
        }

        .btn-add:active {
            transform: translateY(0);
        }

        .todo-list {
            flex: 1;
            overflow-y: auto;
        }

        .empty-state {
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            height: 200px;
            color: #999;
            text-align: center;
        }

        .empty-state p {
            margin: 5px 0;
        }

        .empty-hint {
            font-size: 12px;
            color: #bbb;
        }

        .todo-item {
            display: flex;
            align-items: center;
            padding: 16px 20px;
            border-bottom: 1px solid #f0f0f0;
            gap: 12px;
            transition: background-color 0.2s;
        }

        .todo-item:hover {
            background-color: #f9f9f9;
        }

        .todo-item.completed .todo-text {
            color: #999;
            text-decoration: line-through;
        }

        .checkbox {
            width: 20px;
            height: 20px;
            cursor: pointer;
            accent-color: #667eea;
            flex-shrink: 0;
        }

        .todo-content {
            flex: 1;
            display: flex;
            flex-direction: column;
            gap: 4px;
            min-width: 0;
        }

        .todo-text {
            word-break: break-word;
            color: #333;
            font-size: 15px;
            font-weight: 500;
        }

        .todo-date {
            font-size: 12px;
            color: #999;
        }

        .btn-delete {
            background: #ff6b6b;
            color: white;
            border: none;
            width: 28px;
            height: 28px;
            border-radius: 50%;
            cursor: pointer;
            font-size: 16px;
            display: flex;
            align-items: center;
            justify-content: center;
            flex-shrink: 0;
            transition: background-color 0.2s, transform 0.2s;
        }

        .btn-delete:hover {
            background: #ff5252;
            transform: scale(1.1);
        }

        .btn-delete:active {
            transform: scale(0.95);
        }
    </style>
</head>
<body>
    <div class="container">
        <div class="header">
            <h1>📝 할 일 목록</h1>
            <div class="stats">
                <span class="stat-text" id="stats">할 일 없음</span>
            </div>
        </div>

        <div class="input-group">
            <input
                type="text"
                id="todoInput"
                placeholder="새로운 할 일을 입력하세요..."
                class="input"
            />
            <button onclick="addTodo()" class="btn-add">추가</button>
        </div>

        <div class="todo-list" id="todoList">
            <div class="empty-state">
                <p>할 일이 없습니다</p>
                <p class="empty-hint">위에서 새로운 할 일을 추가해보세요!</p>
            </div>
        </div>
    </div>

    <script>
        let todos = [];

        // 로컬 스토리지에서 할 일 로드
        function loadTodos() {
            const saved = localStorage.getItem('todos');
            todos = saved ? JSON.parse(saved) : [];
            renderTodos();
        }

        // 로컬 스토리지에 할 일 저장
        function saveTodos() {
            localStorage.setItem('todos', JSON.stringify(todos));
        }

        // 할 일 추가
        function addTodo() {
            const input = document.getElementById('todoInput');
            const text = input.value.trim();

            if (text) {
                todos.unshift({
                    id: Date.now(),
                    text: text,
                    completed: false,
                    createdAt: new Date().toLocaleString('ko-KR')
                });
                input.value = '';
                saveTodos();
                renderTodos();
            }
        }

        // 할 일 삭제
        function deleteTodo(id) {
            todos = todos.filter(todo => todo.id !== id);
            saveTodos();
            renderTodos();
        }

        // 할 일 완료 토글
        function toggleTodo(id) {
            const todo = todos.find(t => t.id === id);
            if (todo) {
                todo.completed = !todo.completed;
                saveTodos();
                renderTodos();
            }
        }

        // 할 일 목록 렌더링
        function renderTodos() {
            const list = document.getElementById('todoList');
            const stats = document.getElementById('stats');

            if (todos.length === 0) {
                list.innerHTML = `
                    <div class="empty-state">
                        <p>할 일이 없습니다</p>
                        <p class="empty-hint">위에서 새로운 할 일을 추가해보세요!</p>
                    </div>
                `;
                stats.textContent = '할 일 없음';
                return;
            }

            const completedCount = todos.filter(t => t.completed).length;
            stats.textContent = `${completedCount}/${todos.length} 완료`;

            list.innerHTML = todos.map(todo => `
                <div class="todo-item ${todo.completed ? 'completed' : ''}">
                    <input
                        type="checkbox"
                        ${todo.completed ? 'checked' : ''}
                        onchange="toggleTodo(${todo.id})"
                        class="checkbox"
                    />
                    <div class="todo-content">
                        <span class="todo-text">${escapeHtml(todo.text)}</span>
                        <span class="todo-date">${todo.createdAt}</span>
                    </div>
                    <button onclick="deleteTodo(${todo.id})" class="btn-delete">✕</button>
                </div>
            `).join('');
        }

        // XSS 방지
        function escapeHtml(text) {
            const div = document.createElement('div');
            div.textContent = text;
            return div.innerHTML;
        }

        // Enter 키 처리
        document.getElementById('todoInput').addEventListener('keypress', (e) => {
            if (e.key === 'Enter') {
                addTodo();
            }
        });

        // 초기 로드
        loadTodos();
    </script>
</body>
</html>
EOF

