      color: white;
      border: none;
      padding: 6px 12px;
      border-radius: 4px;
      cursor: pointer;
      font-size: 14px;
      transition: background 0.3s;
    }

    .delete-btn:hover {
      background: #ee5a52;
    }

    .empty-state {
      text-align: center;
      color: #999;
      padding: 40px 20px;
      font-size: 16px;
    }
  </style>
</head>
<body>
  <div class="container">
    <h1>📝 할 일 목록</h1>

    <div class="input-area">
      <input type="text" id="todoInput" placeholder="새로운 할 일을 입력하세요...">
      <button id="addBtn">추가</button>
    </div>

    <div id="todoList" class="todo-list"></div>
  </div>

  <script>
    const todoInput = document.getElementById('todoInput');
    const addBtn = document.getElementById('addBtn');
    const todoList = document.getElementById('todoList');

    let todos = [];

    function loadTodos() {
      const saved = localStorage.getItem('todos');
      todos = saved ? JSON.parse(saved) : [];
      renderTodos();
    }

    function saveTodos() {
      localStorage.setItem('todos', JSON.stringify(todos));
      renderTodos();
    }

    function renderTodos() {
      todoList.innerHTML = '';

      if (todos.length === 0) {
        todoList.innerHTML = '<div class="empty-state">할 일이 없습니다. 새로운 할 일을 추가해보세요!</div>';
        return;
      }

      todos.forEach(todo => {
        const todoItem = document.createElement('div');
        todoItem.className = `todo-item ${todo.completed ? 'completed' : ''}`;

        todoItem.innerHTML = `
          <input type="checkbox" class="todo-checkbox" ${todo.completed ? 'checked' : ''} data-id="${todo.id}">
          <span class="todo-text">${escapeHtml(todo.title)}</span>
          <button class="delete-btn" data-id="${todo.id}">삭제</button>
        `;

        todoList.appendChild(todoItem);
      });

      document.querySelectorAll('.todo-checkbox').forEach(checkbox => {
        checkbox.addEventListener('change', (e) => {
          const id = parseInt(e.target.dataset.id);
          const todo = todos.find(t => t.id === id);
          if (todo) {
            todo.completed = !todo.completed;
            saveTodos();
          }
        });
      });

      document.querySelectorAll('.delete-btn').forEach(btn => {
        btn.addEventListener('click', (e) => {
          const id = parseInt(e.target.dataset.id);
          todos = todos.filter(t => t.id !== id);
          saveTodos();
        });
      });
    }

    function escapeHtml(text) {
      const div = document.createElement('div');
      div.textContent = text;
      return div.innerHTML;
    }

    addBtn.addEventListener('click', () => {
      const title = todoInput.value.trim();
      if (title) {
        todos.push({ id: Date.now(), title, completed: false });
        todoInput.value = '';
        todoInput.focus();
        saveTodos();
      }
    });

    todoInput.addEventListener('keypress', (e) => {
      if (e.key === 'Enter') {
        addBtn.click();
      }
    });

    loadTodos();
  </script>
</body>
</html>
EOF

