    print("❌ downloads 폴더를 찾을 수 없습니다.")
else:
    # 파일들을 확장자별로 그룹화
    files_by_extension = {}

    for file_path in downloads_dir.iterdir():
        if file_path.is_file():
            # 확장자 추출
            if file_path.suffix:
                ext = file_path.suffix[1:].lower()  # .csv -> csv
            else:
                ext = "기타"  # 확장자 없는 파일

            if ext not in files_by_extension:
                files_by_extension[ext] = []
            files_by_extension[ext].append(file_path)

    # 확장자별 폴더 생성 및 파일 이동
    for ext, files in sorted(files_by_extension.items()):
        folder_name = downloads_dir / ext
        folder_name.mkdir(exist_ok=True)

        for file_path in files:
            dest_path = folder_name / file_path.name
            shutil.move(str(file_path), str(dest_path))
            print(f"✓ {file_path.name} → {ext}/ 폴더로 이동")

    print(f"\n✅ 완료! {len(files_by_extension)}개 확장자 그룹으로 정렬되었습니다.")
    print("\n📁 정렬 결과:")
    for ext in sorted(files_by_extension.keys()):
        folder_path = downloads_dir / ext
        file_count = len(list(folder_path.glob("*")))
        print(f"   {ext}/ ({file_count}개 파일)")
EOF

