<!DOCTYPE html>
<html lang="ko">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>테트리스</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            font-family: Arial, sans-serif;
        }

        .container {
            display: flex;
            gap: 30px;
            background: rgba(0, 0, 0, 0.7);
            padding: 30px;
            border-radius: 10px;
            box-shadow: 0 8px 32px rgba(0, 0, 0, 0.3);
        }

        .game-board {
            position: relative;
            width: 200px;
            height: 400px;
            background: #000;
            border: 3px solid #fff;
            display: grid;
            grid-template-columns: repeat(10, 1fr);
            grid-template-rows: repeat(20, 1fr);
            gap: 0;
        }

        .cell {
            border: 1px solid #333;
            background: #000;
        }

        .cell.filled {
            background: #0f0;
            box-shadow: inset 0 0 5px rgba(0, 0, 0, 0.5);
        }

        .cell.cyan { background: #00ffff; }
        .cell.blue { background: #0000ff; }
        .cell.orange { background: #ff8800; }
        .cell.yellow { background: #ffff00; }
        .cell.green { background: #00ff00; }
        .cell.purple { background: #ff00ff; }
        .cell.red { background: #ff0000; }

        .info {
            color: #fff;
            display: flex;
            flex-direction: column;
            gap: 20px;
            min-width: 150px;
        }

        .info h1 {
            font-size: 28px;
            margin-bottom: 10px;
            text-shadow: 0 0 10px rgba(255, 255, 255, 0.3);
        }

        .info-box {
            background: rgba(255, 255, 255, 0.1);
            padding: 15px;
            border-radius: 5px;
            border: 1px solid rgba(255, 255, 255, 0.3);
        }

        .info-box h2 {
            font-size: 14px;
            text-transform: uppercase;
            margin-bottom: 8px;
            color: #64f;
        }

        .info-box p {
            font-size: 24px;
            font-weight: bold;
        }

        .controls {
            background: rgba(255, 255, 255, 0.1);
            padding: 15px;
            border-radius: 5px;
            border: 1px solid rgba(255, 255, 255, 0.3);
            font-size: 12px;
            line-height: 1.8;
        }

        .controls h2 {
            font-size: 14px;
            text-transform: uppercase;
            margin-bottom: 8px;
            color: #64f;
        }

        button {
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            color: white;
            border: none;
            padding: 10px 20px;
            font-size: 16px;
            border-radius: 5px;
            cursor: pointer;
            margin-top: 10px;
            width: 100%;
            transition: opacity 0.3s;
        }

        button:hover {
            opacity: 0.8;
        }

        button:active {
            transform: scale(0.98);
        }

        .game-over {
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            background: rgba(0, 0, 0, 0.95);
            color: #fff;
            padding: 30px;
            border-radius: 10px;
            text-align: center;
            display: none;
            z-index: 100;
            border: 2px solid #f00;
        }

        .game-over.show {
            display: block;
        }

        .game-over h2 {
            font-size: 32px;
            margin-bottom: 10px;
        }

        .game-over p {
            font-size: 18px;
            color: #ccc;
        }
    </style>
</head>
<body>
    <div class="container">
        <div class="game-board" id="gameBoard"></div>

        <div class="info">
            <h1>테트리스</h1>

            <div class="info-box">
                <h2>점수</h2>
                <p id="score">0</p>
            </div>

            <div class="info-box">
                <h2>레벨</h2>
                <p id="level">1</p>
            </div>

            <div class="info-box">
                <h2>라인</h2>
                <p id="lines">0</p>
            </div>

            <button id="startBtn" onclick="toggleGame()">게임 시작</button>

            <div class="controls">
                <h2>조작</h2>
                <div>← → : 이동</div>
                <div>↑ : 회전</div>
                <div>↓ : 빠른 낙하</div>
                <div>스페이스 : 즉시 낙하</div>
            </div>
        </div>
    </div>

    <div class="game-over" id="gameOverScreen">
        <h2>게임 오버</h2>
        <p id="finalScore">최종 점수: 0</p>
    </div>

    <script>
        const COLS = 10;
        const ROWS = 20;

        const TETROMINOS = [
            { shape: [[1,1,1,1]], color: 'cyan' },
            { shape: [[1,1],[1,1]], color: 'yellow' },
            { shape: [[0,1,0],[1,1,1]], color: 'purple' },
            { shape: [[1,0,0],[1,1,1]], color: 'blue' },
            { shape: [[0,0,1],[1,1,1]], color: 'orange' },
            { shape: [[0,1,1],[1,1,0]], color: 'green' },
            { shape: [[1,1,0],[0,1,1]], color: 'red' }
        ];

        let board = Array(ROWS).fill(null).map(() => Array(COLS).fill(null));
        let currentPiece = null;
        let currentX = 0;
        let currentY = 0;
        let gameRunning = false;
        let score = 0;
        let lines = 0;
        let level = 1;
        let dropInterval = 800;
        let lastDropTime = 0;

        const gameBoard = document.getElementById('gameBoard');
        const scoreDisplay = document.getElementById('score');
        const levelDisplay = document.getElementById('level');
        const linesDisplay = document.getElementById('lines');
        const gameOverScreen = document.getElementById('gameOverScreen');
        const finalScoreDisplay = document.getElementById('finalScore');
        const startBtn = document.getElementById('startBtn');

        function createCells() {
            gameBoard.innerHTML = '';
            for (let y = 0; y < ROWS; y++) {
                for (let x = 0; x < COLS; x++) {
                    const cell = document.createElement('div');
                    cell.className = 'cell';
                    cell.id = `cell-${x}-${y}`;
                    gameBoard.appendChild(cell);
                }
            }
        }

        function getRandomPiece() {
            return JSON.parse(JSON.stringify(TETROMINOS[Math.floor(Math.random() * TETROMINOS.length)]));
        }

        function rotatePiece(piece) {
            const n = piece.shape.length;
            const rotated = Array(piece.shape[0].length).fill(null).map(() => Array(n).fill(0));
            for (let y = 0; y < n; y++) {
                for (let x = 0; x < piece.shape[0].length; x++) {
                    rotated[x][n - 1 - y] = piece.shape[y][x];
                }
            }
            return { shape: rotated, color: piece.color };
        }

        function isValidPosition(piece, x, y) {
            for (let py = 0; py < piece.shape.length; py++) {
                for (let px = 0; px < piece.shape[py].length; px++) {
                    if (piece.shape[py][px]) {
                        const nx = x + px;
                        const ny = y + py;
                        if (nx < 0 || nx >= COLS || ny >= ROWS) return false;
                        if (ny >= 0 && board[ny][nx]) return false;
                    }
                }
            }
            return true;
        }

        function placePiece() {
            for (let py = 0; py < currentPiece.shape.length; py++) {
                for (let px = 0; px < currentPiece.shape[py].length; px++) {
                    if (currentPiece.shape[py][px]) {
                        const x = currentX + px;
                        const y = currentY + py;
                        if (y >= 0) board[y][x] = currentPiece.color;
                    }
                }
            }
        }

        function clearLines() {
            let clearedLines = 0;
            for (let y = ROWS - 1; y >= 0; y--) {
                if (board[y].every(cell => cell)) {
                    board.splice(y, 1);
                    board.unshift(Array(COLS).fill(null));
                    clearedLines++;
                    y++;
                }
            }

            if (clearedLines > 0) {
                score += clearedLines * clearedLines * 100;
                lines += clearedLines;
                level = Math.floor(lines / 10) + 1;
                dropInterval = Math.max(200, 800 - (level - 1) * 50);
            }
        }

        function spawnPiece() {
            currentPiece = getRandomPiece();
            currentX = Math.floor(COLS / 2) - 1;
            currentY = 0;

            if (!isValidPosition(currentPiece, currentX, currentY)) {
                endGame();
            }
        }

        function updateDisplay() {
            for (let y = 0; y < ROWS; y++) {
                for (let x = 0; x < COLS; x++) {
                    const cell = document.getElementById(`cell-${x}-${y}`);
                    cell.className = 'cell';
                    if (board[y][x]) {
                        cell.classList.add(board[y][x], 'filled');
                    }
                }
            }

            if (currentPiece) {
                for (let py = 0; py < currentPiece.shape.length; py++) {
                    for (let px = 0; px < currentPiece.shape[py].length; px++) {
                        if (currentPiece.shape[py][px]) {
                            const x = currentX + px;
                            const y = currentY + py;
                            if (y >= 0 && y < ROWS && x >= 0 && x < COLS) {
                                const cell = document.getElementById(`cell-${x}-${y}`);
                                cell.className = `cell ${currentPiece.color} filled`;
                            }
                        }
                    }
                }
            }

            scoreDisplay.textContent = score;
            levelDisplay.textContent = level;
            linesDisplay.textContent = lines;
        }

        function moveDown() {
            if (isValidPosition(currentPiece, currentX, currentY + 1)) {
                currentY++;
            } else {
                placePiece();
                clearLines();
                spawnPiece();
            }
        }

        function endGame() {
            gameRunning = false;
            gameOverScreen.classList.add('show');
            finalScoreDisplay.textContent = `최종 점수: ${score}`;
            startBtn.textContent = '다시 시작';
        }

        function toggleGame() {
            if (gameRunning) {
                gameRunning = false;
                startBtn.textContent = '게임 재개';
            } else {
                if (score === 0) {
                    board = Array(ROWS).fill(null).map(() => Array(COLS).fill(null));
                    score = 0;
                    lines = 0;
                    level = 1;
                    dropInterval = 800;
                }
                gameRunning = true;
                gameOverScreen.classList.remove('show');
                startBtn.textContent = '게임 일시정지';
                spawnPiece();
                lastDropTime = Date.now();
                gameLoop();
            }
        }

        function gameLoop() {
            if (!gameRunning) return;

            const now = Date.now();
            if (now - lastDropTime > dropInterval) {
                moveDown();
                lastDropTime = now;
            }

            updateDisplay();
            requestAnimationFrame(gameLoop);
        }

        document.addEventListener('keydown', (e) => {
            if (!gameRunning) return;

            switch(e.key) {
                case 'ArrowLeft':
                    if (isValidPosition(currentPiece, currentX - 1, currentY)) currentX--;
                    e.preventDefault();
                    break;
                case 'ArrowRight':
                    if (isValidPosition(currentPiece, currentX + 1, currentY)) currentX++;
                    e.preventDefault();
                    break;
                case 'ArrowUp':
                    const rotated = rotatePiece(currentPiece);
                    if (isValidPosition(rotated, currentX, currentY)) currentPiece = rotated;
                    e.preventDefault();
                    break;
                case 'ArrowDown':
                    moveDown();
                    e.preventDefault();
                    break;
                case ' ':
                    while (isValidPosition(currentPiece, currentX, currentY + 1)) currentY++;
                    e.preventDefault();
                    break;
            }
            updateDisplay();
        });

        createCells();
        updateDisplay();
    </script>
</body>
</html>
EOF

cat > server/server.js << 'EOF'
import express from 'express';
import cors from 'cors';
import { initDB, getDB } from './db.js';
import bcrypt from 'bcryptjs';
import jwt from 'jsonwebtoken';

const app = express();
const PORT = 5000;
const JWT_SECRET = 'your-secret-key-change-in-production';

app.use(cors());
app.use(express.json());

const verifyToken = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) return res.status(401).json({ message: 'No token' });

  try {
    const decoded = jwt.verify(token, JWT_SECRET);
    req.userId = decoded.id;
    next();
  } catch {
    res.status(403).json({ message: 'Invalid token' });
  }
};

app.post('/api/auth/register', (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) return res.status(400).json({ message: 'Missing fields' });

  const hashedPassword = bcrypt.hashSync(password, 10);
  const db = getDB();

  db.run(
    'INSERT INTO users (username, password) VALUES (?, ?)',
    [username, hashedPassword],
    function(err) {
      if (err) return res.status(400).json({ message: 'Username already exists' });
      res.json({ id: this.lastID, username });
    }
  );
});

app.post('/api/auth/login', (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) return res.status(400).json({ message: 'Missing fields' });

  const db = getDB();
  db.get('SELECT * FROM users WHERE username = ?', [username], (err, user) => {
    if (err || !user) return res.status(401).json({ message: 'Invalid credentials' });

    if (!bcrypt.compareSync(password, user.password)) {
      return res.status(401).json({ message: 'Invalid credentials' });
    }

    const token = jwt.sign({ id: user.id, username: user.username }, JWT_SECRET, { expiresIn: '7d' });
    res.json({ token, user: { id: user.id, username: user.username } });
  });
});

app.post('/api/expenses', verifyToken, (req, res) => {
  const { type, category, amount, description, date } = req.body;
  const db = getDB();

  db.run(
    'INSERT INTO expenses (userId, type, category, amount, description, date) VALUES (?, ?, ?, ?, ?, ?)',
    [req.userId, type, category, amount, description, date],
    function(err) {
      if (err) return res.status(500).json({ message: 'Error creating expense' });
      res.json({ id: this.lastID, userId: req.userId, type, category, amount, description, date });
    }
  );
});

app.get('/api/expenses', verifyToken, (req, res) => {
  const db = getDB();
  db.all(
    'SELECT * FROM expenses WHERE userId = ? ORDER BY date DESC',
    [req.userId],
    (err, expenses) => {
      if (err) return res.status(500).json({ message: 'Error fetching expenses' });
      res.json(expenses);
    }
  );
});

app.delete('/api/expenses/:id', verifyToken, (req, res) => {
  const db = getDB();
  db.run(
    'DELETE FROM expenses WHERE id = ? AND userId = ?',
    [req.params.id, req.userId],
    function(err) {
      if (err) return res.status(500).json({ message: 'Error deleting expense' });
      res.json({ message: 'Expense deleted' });
    }
  );
});

async function startServer() {
  try {
    await initDB();
    app.listen(PORT, () => console.log(`Server running on port ${PORT}`));
  } catch (err) {
    console.error('Failed to start server:', err);
    process.exit(1);
  }
}

startServer();
EOF

cat > ./client/src/components/Login.jsx << 'EOF'
import { useState } from 'react'
import { login, register } from '../api'
import './Login.css'

export default function Login({ onLogin }) {
  const [isLogin, setIsLogin] = useState(true)
  const [username, setUsername] = useState('')
  const [password, setPassword] = useState('')
  const [error, setError] = useState('')
  const [loading, setLoading] = useState(false)

  const handleSubmit = async (e) => {
    e.preventDefault()
    setError('')
    setLoading(true)

    try {
      if (isLogin) {
        const response = await login(username, password)
        localStorage.setItem('token', response.data.token)
        localStorage.setItem('username', response.data.user.username)
        onLogin(response.data.user.username)
      } else {
        await register(username, password)
        const loginResponse = await login(username, password)
        localStorage.setItem('token', loginResponse.data.token)
        localStorage.setItem('username', loginResponse.data.user.username)
        onLogin(loginResponse.data.user.username)
      }
    } catch (err) {
      setError(err.response?.data?.message || '오류가 발생했습니다')
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="login-container">
      <div className="login-card">
        <h2>{isLogin ? '로그인' : '회원가입'}</h2>

        {error && <div className="error-message">{error}</div>}

        <form onSubmit={handleSubmit}>
          <div className="form-group">
            <label>사용자명</label>
            <input
              type="text"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              placeholder="사용자명을 입력하세요"
              required
            />
          </div>

          <div className="form-group">
            <label>비밀번호</label>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="비밀번호를 입력하세요"
              required
            />
          </div>

          <button 
            type="submit" 
            className="submit-btn"
            disabled={loading}
          >
            {loading ? '진행 중...' : isLogin ? '로그인' : '회원가입'}
          </button>
        </form>

        <div className="toggle-mode">
          <span>
            {isLogin ? '계정이 없으신가요? ' : '이미 계정이 있으신가요? '}
            <button 
              type="button" 
              onClick={() => {
                setIsLogin(!isLogin)
                setError('')
              }}
              className="toggle-btn"
            >
              {isLogin ? '회원가입하기' : '로그인하기'}
            </button>
          </span>
        </div>
      </div>
    </div>
  )
}
EOF

